import json
n=28
# panel spans are defined by the separator lines at 4,9,14,19,24
spans=[(0,3),(5,8),(10,13),(15,18),(20,23),(25,27)]
g=[[0]*n for _ in range(n)]
for i in [4,9,14,19,24]:
    for j in range(n): g[i][j]=8; g[j][i]=8
# Based on demo: connect aligned same-color markers across panel-block coordinates.
# 3: blocks (row 0,col 2) to (row 4,col 2) => vertical bar through blocks 0..4.
# 2: blocks (row 1,col 0) to (row 1,col 4) => horizontal bar; plus col 0 row 1..3.
for rb in range(0,5):
    for r in range(*spans[rb]):
        for c in range(*spans[2]): g[r][c]=3
for cb in range(0,5):
    for r in range(*spans[1]):
        for c in range(*spans[cb]): g[r][c]=2
for rb in range(1,4):
    for r in range(*spans[rb]):
        for c in range(*spans[0]): g[r][c]=2
# overlap of 2 and 3 is 6
for r in range(n):
    for c in range(n):
        if g[r][c]==2 and r in range(*spans[1]) and c in range(*spans[2]): g[r][c]=6
assert len(g)==28 and all(len(row)==28 for row in g)
print(json.dumps({'action':'submit','grid':g},separators=(',',':')))

import json
n=28
spans=[(0,4),(5,9),(10,14),(15,19),(20,24),(25,28)]
g=[[0]*n for _ in range(n)]
for x in (4,9,14,19,24):
 for j in range(n): g[x][j]=8; g[j][x]=8
# Connect same-color marker panels by straight axis-aligned paths.
def fill_panel(rb,cb,color):
 for r in range(*spans[rb]):
  for c in range(*spans[cb]):
   if g[r][c] in (0,color): g[r][c]=color
   elif g[r][c] != color: g[r][c]=6
# color 3 line from panel (0,2) through (4,2)
for rb in range(0,5): fill_panel(rb,2,3)
# color 2 L network joining markers (1,0),(1,4),(3,0)
for cb in range(0,5): fill_panel(1,cb,2)
for rb in range(1,4): fill_panel(rb,0,2)
assert len(g)==28 and all(len(row)==28 for row in g) and all(0<=v<=9 for row in g for v in row)
print(json.dumps({'action':'submit','grid':g},separators=(',',':')))
